def gen(rng):
    PREC = {'+': 1, '-': 1, '*': 2, '/': 2}

    def rand_tree(nops):
        # returns ('num', v) or (op, left, right)
        if nops == 0:
            return ('num', str(rng.choice([rng.randint(0, 9), rng.randint(0, 999)])))
        l = rng.randint(0, nops - 1)
        return (rng.choice('+-*/'), rand_tree(l), rand_tree(nops - 1 - l))

    def render(t, extra):
        if t[0] == 'num':
            s = [t[1]]
            if rng.random() < extra:
                s = ['('] + s + [')']
            return s
        op = t[0]
        left, right = t[1], t[2]
        ls = render(left, extra)
        rs = render(right, extra)
        if left[0] != 'num' and PREC[left[0]] < PREC[op] and ls[0] != '(' or (left[0] != 'num' and PREC[left[0]] < PREC[op] and not wrapped(ls)):
            ls = ['('] + ls + [')']
        if right[0] != 'num' and PREC[right[0]] <= PREC[op] and not wrapped(rs):
            rs = ['('] + rs + [')']
        s = ls + [op] + rs
        if rng.random() < extra:
            s = ['('] + s + [')']
        return s

    def wrapped(s):
        # does the token list start with '(' that closes only at the very end?
        if s[0] != '(' or s[-1] != ')':
            return False
        d = 0
        for i, x in enumerate(s):
            if x == '(':
                d += 1
            elif x == ')':
                d -= 1
                if d == 0 and i != len(s) - 1:
                    return False
        return True

    def line(toks):
        return ' '.join(toks)

    tests = [line(['7']), line(['(', '7', ')']), line(['0', '+', '0']), line(['3', '+', '4', '*', '2']),
             line(['8', '-', '3', '-', '2']), line(['8', '-', '(', '3', '-', '2', ')']),
             line(['(', '(', '(', '1', ')', ')', ')']), line(['1', '/', '2', '/', '3', '*', '4']),
             line(['2', '*', '3', '+', '4', '*', '5', '-', '6', '/', '7'])]
    for nops in (1, 2, 3, 4, 5, 6, 8, 10):
        for extra in (0.0, 0.2):
            tests.append(line(render(rand_tree(nops), extra)))
    for _ in range(4):
        tests.append(line(render(rand_tree(rng.randint(10, 14)), 0.1)))

    # large cases (about 10^5 tokens)
    n = 50000
    # long left chain of equal precedence
    toks = ['1']
    for i in range(n - 1):
        toks += [rng.choice('+-'), str(rng.randint(0, 999))]
    tests.append(line(toks))
    # flat expression mixing precedences
    toks = [str(rng.randint(0, 999))]
    for i in range(n - 1):
        toks += [rng.choice('+-*/'), str(rng.randint(0, 999))]
    tests.append(line(toks))
    # right-nested chain with parentheses (depth 5000)
    d = 5000
    toks = []
    for i in range(d):
        toks += [str(rng.randint(0, 999)), rng.choice('+-*/'), '(']
    toks += ['1'] + [')'] * d
    tests.append(line(toks))
    # random balanced-ish tree with many nodes
    t = rand_tree(25000)
    tests.append(line(render(t, 0.02)))
    return tests
